import 'dart:convert';
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:pomodoro_domain/pomodoro_domain.dart';
import 'package:pip_garden/src/garden/art_bundle.dart';
import 'package:pip_garden/src/garden/plant_sprite.dart';

// Art loaded from files and painted through PlantSpriteRegistry. Checks
// that a decoded PNG satisfies the same interface the placeholder shapes did.
// Runs against whatever is in assets/art/ (currently generated by
// tool/generate_sprite_art.dart).

const PlantPalette _green = PlantPalette(
  foliage: Color(0xFF00FF00),
  bloom: Color(0xFF00FF00),
  soil: Color(0xFF00FF00),
);

const PlantPalette _red = PlantPalette(
  foliage: Color(0xFFFF0000),
  bloom: Color(0xFFFF0000),
  soil: Color(0xFFFF0000),
);

/// Paints [sprite] into a [side] square and returns its RGBA pixels.
Future<Uint32List> _pixels(
  PlantSprite sprite,
  PlantPalette palette, {
  int side = 64,
}) async {
  final recorder = ui.PictureRecorder();
  final canvas = ui.Canvas(recorder);
  sprite.paint(
    canvas,
    ui.Rect.fromLTWH(0, 0, side.toDouble(), side.toDouble()),
    palette,
  );

  final picture = recorder.endRecording();
  final image = await picture.toImage(side, side);
  picture.dispose();

  final data = await image.toByteData();
  image.dispose();
  return data!.buffer.asUint32List();
}

/// Count of pixels that aren't fully transparent.
int _inked(Uint32List pixels) =>
    pixels.where((pixel) => (pixel >> 24) & 0xFF != 0).length;

/// Serves only what it's given and throws otherwise, like rootBundle does for
/// a missing asset.
class _FakeBundle extends CachingAssetBundle {
  _FakeBundle(this.entries);

  final Map<String, ByteData> entries;

  @override
  Future<ByteData> load(String key) async {
    final data = entries[key];
    if (data == null) throw FlutterError('no asset at $key');
    return data;
  }
}

ByteData _text(String value) =>
    ByteData.sublistView(Uint8List.fromList(utf8.encode(value)));

void main() {
  // Plain test()s don't get a binding for free; asset access needs one.
  TestWidgetsFlutterBinding.ensureInitialized();

  group('the manifest', () {
    test('reads a plant, its mask and its footprint', () {
      final manifest = ArtManifest.parse(jsonEncode({
        'plants': [
          {
            'form': 'leafy',
            'stage': 'sprout',
            'art': 'a.png',
            'roles': 'a.roles.png',
            'footprint': [0.1, 0.2, 0.8, 1.0],
          },
        ],
        'decor': <Object?>[],
      }));

      final entry = manifest.plants[(PlantForm.leafy, GrowthStage.sprout)]!;
      expect(entry.art, 'a.png');
      expect(entry.roles, 'a.roles.png');
      expect(entry.footprint, const ui.Rect.fromLTRB(0.1, 0.2, 0.8, 1));
    });

    test('allows a drawing with no mask', () {
      final manifest = ArtManifest.parse(jsonEncode({
        'plants': <Object?>[],
        'decor': [
          {'kind': 'pond', 'art': 'p.png', 'footprint': [0, 0, 1, 1]},
        ],
      }));

      expect(manifest.decor[DecorKind.pond]!.roles, isNull);
    });

    test('lists each image path once', () {
      final manifest = ArtManifest.parse(jsonEncode({
        'plants': [
          {
            'form': 'leafy',
            'stage': 'sprout',
            'art': 'a.png',
            'roles': 'shared.png',
            'footprint': [0, 0, 1, 1],
          },
          {
            'form': 'leafy',
            'stage': 'young',
            'art': 'b.png',
            'roles': 'shared.png',
            'footprint': [0, 0, 1, 1],
          },
        ],
        'decor': <Object?>[],
      }));

      // A set, so a shared mask is decoded once.
      expect(manifest.imagePaths.toSet(), {'a.png', 'b.png', 'shared.png'});
      expect(manifest.imagePaths.length, 3);
    });

    test('rejects a row with no footprint', () {
      // Guessing would mean the whole box, and the hit-test would give empty
      // sky to a plant.
      expect(
        () => ArtManifest.parse(jsonEncode({
          'plants': [
            {'form': 'leafy', 'stage': 'sprout', 'art': 'a.png'},
          ],
          'decor': <Object?>[],
        })),
        throwsA(isA<ArtBundleException>()),
      );
    });

    test('rejects an unknown plant form', () {
      expect(
        () => ArtManifest.parse(jsonEncode({
          'plants': [
            {
              'form': 'triffid',
              'stage': 'sprout',
              'art': 'a.png',
              'footprint': [0, 0, 1, 1],
            },
          ],
          'decor': <Object?>[],
        })),
        throwsA(isA<ArtBundleException>()),
      );
    });

    test('rejects invalid JSON', () {
      expect(
        () => ArtManifest.parse('not json'),
        throwsA(isA<ArtBundleException>()),
      );
    });
  });

  group('loading a bundle', () {
    test('rejects a set missing a plant', () async {
      // Throw rather than fall back: a half-delivered set would ship with
      // holes.
      final bundle = _FakeBundle({
        ArtBundle.manifestAsset: _text(jsonEncode({
          'plants': [
            {
              'form': 'leafy',
              'stage': 'sprout',
              'art': 'a.png',
              'footprint': [0, 0, 1, 1],
            },
          ],
          'decor': <Object?>[],
        })),
        'a.png': await _onePixelPng(),
      });

      await expectLater(
        ArtBundle.load(bundle),
        throwsA(
          isA<ArtBundleException>().having(
            (it) => it.message,
            'message',
            contains('no art for'),
          ),
        ),
      );
    });

    test('rejects a missing file', () async {
      final bundle = _FakeBundle({
        ArtBundle.manifestAsset: _text(jsonEncode({
          'plants': [
            {
              'form': 'leafy',
              'stage': 'sprout',
              'art': 'missing.png',
              'footprint': [0, 0, 1, 1],
            },
          ],
          'decor': <Object?>[],
        })),
      });

      await expectLater(
        ArtBundle.load(bundle),
        throwsA(
          isA<ArtBundleException>().having(
            (it) => it.message,
            'message',
            contains('missing.png'),
          ),
        ),
      );
    });
  });

  group('shipped art', () {
    late ArtBundle art;

    setUpAll(() async => art = await ArtBundle.load(rootBundle));
    tearDownAll(() => art.dispose());

    test('covers every plant form at every stage', () {
      // Against the real asset bundle: 70 combinations.
      for (final form in PlantForm.values) {
        for (final stage in GrowthStage.values) {
          expect(
            () => art.plants.spriteFor(form: form, stage: stage),
            returnsNormally,
            reason: '${form.name} at ${stage.name} has no art',
          );
        }
      }
    });

    test('covers every decor kind', () {
      for (final kind in DecorKind.values) {
        expect(() => art.decor.spriteFor(kind), returnsNormally);
      }
    });

    test('every sprite paints something', () async {
      // A sprite that paints nothing would pass every other test here.
      for (final form in PlantForm.values) {
        for (final stage in GrowthStage.values) {
          final pixels = await _pixels(
            art.plants.spriteFor(form: form, stage: stage),
            _green,
          );
          expect(
            _inked(pixels),
            greaterThan(0),
            reason: '${form.name} at ${stage.name} painted nothing',
          );
        }
      }
    });

    test('mask applies the palette', () async {
      // The point of the mask: fixed art still changes with season, theme and
      // species.
      final sprite = art.plants.spriteFor(
        form: PlantForm.broadleaf,
        stage: GrowthStage.mature,
      );

      final green = await _pixels(sprite, _green);
      final red = await _pixels(sprite, _red);

      expect(green, isNot(red), reason: 'the palette did not reach the art');

      // Colour changed, not shape.
      expect(_inked(green), _inked(red));
    });

    test('decodes within the launch budget', () async {
      // Launch-to-garden budget is 1.5s and ArtGate spends part of it.
      //
      // Loose bound (debug host build), but tight enough to catch decodes going
      // serial.
      final clock = Stopwatch()..start();
      final second = await ArtBundle.load(rootBundle);
      clock.stop();
      second.dispose();

      final sprites = PlantForm.values.length * GrowthStage.values.length +
          DecorKind.values.length;
      debugPrint(
        'art baseline | decoding $sprites sprites: '
        '${clock.elapsedMilliseconds} ms',
      );
      expect(clock.elapsedMilliseconds, lessThan(1500));
    });

    test('footprint matches the sprite', () {
      // Manifest footprint vs the sprite's own, scaled. Used by hit-testing.
      final sprite = art.plants.spriteFor(
        form: PlantForm.posy,
        stage: GrowthStage.mature,
      );

      const box = ui.Rect.fromLTWH(100, 200, 80, 80);
      final footprint = sprite.footprintIn(box);

      expect(footprint.left, greaterThanOrEqualTo(box.left - 0.01));
      expect(footprint.right, lessThanOrEqualTo(box.right + 0.01));
      expect(footprint.width, greaterThan(0));
      expect(footprint.height, greaterThan(0));
    });

    test('mature fills more than seed', () async {
      // Can't judge the silhouettes, but the five stages should differ and get
      // bigger.
      for (final form in PlantForm.values) {
        final inked = <int>[];
        final drawings = <String>{};

        for (final stage in GrowthStage.values) {
          final pixels = await _pixels(
            art.plants.spriteFor(form: form, stage: stage),
            _green,
            side: 128,
          );
          inked.add(_inked(pixels));
          drawings.add(_fingerprint(pixels));
        }

        expect(
          inked.last,
          greaterThan(inked.first),
          reason: '${form.name} does not end up bigger than it started',
        );

        // Compare pictures, not areas; two stages could share a pixel count.
        expect(
          drawings,
          hasLength(GrowthStage.values.length),
          reason: '${form.name} draws the same picture at two stages',
        );
      }
    });
  });
}

/// Cheap image identity, enough to tell drawings apart.
String _fingerprint(Uint32List pixels) {
  var hash = 17;
  for (final pixel in pixels) {
    hash = (hash * 31 + pixel) & 0xFFFFFFFF;
  }
  return '$hash:${_inked(pixels)}';
}

/// Smallest valid PNG, for tests that just need something decodable.
Future<ByteData> _onePixelPng() async {
  final recorder = ui.PictureRecorder();
  ui.Canvas(recorder).drawRect(
    const ui.Rect.fromLTWH(0, 0, 1, 1),
    ui.Paint()..color = const Color(0xFFFFFFFF),
  );
  final picture = recorder.endRecording();
  final image = await picture.toImage(1, 1);
  picture.dispose();

  final png = await image.toByteData(format: ui.ImageByteFormat.png);
  image.dispose();
  return png!;
}
